def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70

    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    total_alive = 1 + len(alive)
    expected_units = supply / float(WATER_REQ)
    scarcity = expected_units < total_alive
    severe_scarcity = expected_units < max(1.0, total_alive - 1)

    opp_bids = []
    bob_bid = None
    cindy_bid = None
    urgent_opp = 0
    for oid, opp in alive:
        prev = opp.get('previous_trace') or {}
        pbid = prev.get('bid')
        if pbid is not None:
            opp_bids.append(float(pbid))
            if oid == 'Bob':
                bob_bid = float(pbid)
            elif oid == 'Cindy':
                cindy_bid = float(pbid)
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
            urgent_opp += 1

    highest_prev = max(opp_bids) if opp_bids else 0.0
    pressure = highest_prev
    if bob_bid is not None:
        pressure = max(pressure, bob_bid)
    if cindy_bid is not None:
        pressure = max(pressure, cindy_bid)

    critical_me = (hp <= 3) or (no_water >= 1)
    very_safe = (hp >= 8 and no_water == 0)

    if not alive:
        return float(min(budget, 20.0))

    if critical_me:
        base = max(88.0, pressure + 3.0)
        if severe_scarcity or urgent_opp >= 2:
            base = max(base, 102.0)
        return float(min(budget, base))

    if not scarcity and very_safe:
        base = 18.0
        if pressure > 110:
            base = 12.0
        return float(min(budget, base))

    if not scarcity:
        base = 28.0 + 4.0 * no_water
        if urgent_opp >= 2:
            base += 8.0
        return float(min(budget, base))

    if severe_scarcity:
        if very_safe and pressure >= 90:
            return float(min(budget, 24.0))
        base = max(76.0, min(pressure + 2.0, 98.0))
        if urgent_opp >= 2:
            base += 6.0
        return float(min(budget, base))

    base = max(58.0, min(pressure + 1.5, 92.0))
    if very_safe and pressure >= 95:
        base = 34.0
    elif hp <= 5:
        base = max(base, 72.0)
    return float(min(budget, base))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
