    num_alive_players = len(alive_opponents) + 1 

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    base_bid = DAILY_SALARY * 0.6

    if my_status['hp'] <= 3:
        base_bid = DAILY_SALARY * 0.9
    elif my_status['hp'] <= 5:
        base_bid = DAILY_SALARY * 0.75
    else:
        base_bid = DAILY_SALARY * 0.5

    available_water_units = int(day_context['supply'] // WATER_REQ)

    if available_water_units < num_alive_players:
        base_bid *= 1.2
        if my_status['hp'] <= 2:
            base_bid = DAILY_SALARY * 0.95
    elif available_water_units >= num_alive_players:
        base_bid *= 0.8

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            base_bid = max(base_bid, highest_prev_bid * 1.05)
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            base_bid = max(base_bid, highest_prev_bid + 1.0)
        else:
            base_bid = max(base_bid, highest_prev_bid * 1.1)

    final_bid = min(my_status['budget'], base_bid)

    if my_status['hp'] < EPISODE_DAYS - day_context['day'] + 1:
        final_bid = max(final_bid, DAILY_SALARY * 0.2)

    if my_status['no_water_days'] > 0:
        final_bid = min(my_status['budget'], DAILY_SALARY * 0.99)

    return max(0.0, final_bid)

