def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids and any high-pressure signal
    prev_bids = []
    high_pressure = False
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
            except Exception:
                b = None
        if b is not None:
            prev_bids.append(b)
            if b >= DAILY_SALARY * 0.85:
                high_pressure = True

    # Estimate how many full water units supply can support (not perfect, but guides aggressiveness)
    # Use int() to avoid float index issues.
    capacity_units = int(supply // float(WATER_REQ)) if float(WATER_REQ) > 0 else 0

    # Baseline bid: mid-tier bid to secure water without burning budget
    # If supply can support multiple units, we can bid less.
    if capacity_units >= 2:
        baseline = DAILY_SALARY * 0.55
    else:
        baseline = DAILY_SALARY * 0.65

    # React to our own urgency
    if my_hp <= 2 or my_no_water_days >= 2:
        urgency = 0.9
    elif my_hp <= 3 or my_no_water_days == 1:
        urgency = 0.75
    else:
        urgency = 0.6

    # React to opponents' yesterday behavior
    if prev_bids:
        highest_prev_bid = max(prev_bids)
    else:
        highest_prev_bid = 0.0

    if high_pressure:
        # Match/just exceed the pressure to prevent being outbid.
        target = min(my_budget, max(baseline, highest_prev_bid + 2.0))
    else:
        # If no one was extremely high, aim slightly above typical mid bids.
        # Yesterday Cindy averaged ~75.6; aim around 78-85 depending on urgency.
        target = baseline * urgency
        if prev_bids:
            # Nudge above second-highest to beat mid bidders.
            sorted_bids = sorted(prev_bids)
            idx = int(max(0, len(sorted_bids) - 2))
            second_highest = float(sorted_bids[idx])
            target = max(target, second_highest * 1.05)

    # Clamp to budget and reasonable upper bound
    target = float(min(my_budget, target))
    # Ensure we don't bid trivially low when we need survival
    min_bid = 5.0
    if my_hp <= 3:
        min_bid = 30.0
    target = float(max(min_bid, target))

    return target
